  'Deze afbeelding naar het AI-model sturen?':
      'Kas saata see pilt tehisintellekti mudelile?',
  'De afbeelding gaat ongewijzigd naar':
      'Pilt saadetakse muutmata kujul aadressile',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck ei redigeeri pildil midagi: näod, ekraanipildil olev tekst ja nähtavad andmed lähevad kaasa.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Pildikontroll leidis siit ühe või mitu äratuntavat nägu.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Ekspordi kõrvale kirjutatakse kaks faili, mille abil saaja saab redigeerimised üle kontrollida.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'loetleb, mis on välja jäetud, ilma väärtusteta endita. Selle faili võib aruandega kaasa panna.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'sisaldab võtmeid, millega saab iga redigeeritud väärtuse tagasi arvutada. Ära saada seda faili kaasa: siis on redigeerimine tühistatud. Hoia seda allika juures.',
  'slides': 'slaidi',
  'Achtergehouden': 'Kinni peetud',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Kinni peetud: klassifitseeritud rangemalt kui esitlus',
  '1 slide achtergehouden door haar TLP': '1 slaid peeti kinni selle TLP tõttu',
  'slides achtergehouden door hun TLP': 'slaidi peeti kinni nende TLP tõttu',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Neid slaide ei võeta kaasa esitamisel, eksportimisel ega paketti. Tõsta esitluse teabes esitluse TLP-taset, et need kaasa võtta.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Kõik slaidid on nende TLP-klassifikatsiooni tõttu kinni peetud — pole midagi näidata.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Kõik slaidid on nende TLP-klassifikatsiooni tõttu kinni peetud — pole midagi eksportida.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Kõik slaidid on vahele jäetud või nende TLP-klassifikatsiooni tõttu kinni peetud — pole midagi näidata.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Kõik slaidid on vahele jäetud või nende TLP-klassifikatsiooni tõttu kinni peetud — pole midagi eksportida.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Diagrammi arve ei salvestatud — need on alles ainult selles aknas:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Brauseris pole krahhitaastet: kui sulged selle vahekaardi, on salvestamata töö kadunud. Salvesta oma esitlus ise.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Kohalik CVE andmebaas (allalaadimise käivitate ise): OciDeck toob masskogumi aadressi api.github.com kaudu ja selle väljalaskefaili, millele see aadress osutab.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE otsing (vaikimisi väljas): kui see on sees, läheb teie otsingusõna määratud CVE peeglisse ja, kui see midagi ei leia, ENISA Euroopa andmebaasi ja MITRE-sse.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Manustatud YouTube\'i või Vimeo video laadib mängija sellelt teenuselt.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Brauseris: kui brauser keeldub aadressi otse hankimast, proovib OciDeck seda uuesti selle serveri kaudu, kust rakendus tuli; siis jõuab see aadress tolle serverini.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Tagasivõtmist ei salvestatud. Järgmisel käivitamisel kehtib teie nõusolek taas.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Vahepealkiri, mis kuulutab ette esitluse uue osa. Hoia see lühike. Lisa taustapilt pildikogust.',
  'Bronnen doorzoeken…': 'Otsitakse allikatest…',
  'Niet doorzocht': 'Ei otsitud',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'See kontroll veebiversioonis ei tööta: näotuvastus vajab süsteemiteeki, mida brauseris pole. Piltide näotuvastuseks kasuta lauaarvuti versiooni.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Luba vajab hoidlas lugemis- ja kirjutamisõigust. Giteal ja Forgejol pole serveripoolset otsingut; OciDeck otsib kohapeal.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Luba vajab repo ulatust (või täpselt: Contents lugemine ja kirjutamine).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Luba vajab read_repository, write_repository ja read_api. Serveripoolne otsing nõuab Advanced või Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Kiire serveripoolne otsing — indekseerimise viivituse tõttu võib äsja muudetud pakk puududa.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Meediat ei säilitata tavalises .md-failis',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Sellel vahekaardil valitud pildid, video ja heli asuvad ainult mälus. Tavaline .md-fail neid ei säilita — uuesti avades on need kadunud. Ekspordi .ocideck-paketina, et meedia endaga kaasa võtta.',
  'Media verwijderd om privacyredenen':
      'Meedia eemaldatud privaatsuse kaalutlustel',
  'Afbeeldingen door AI laten taggen?':
      'Kas lasta tehisintellektil need pildid sildistada?',
