  'Vingerafdruk (SHA-256)': 'Sõrmejälg (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Usaldatakse ainult seda üht sertifikaati. Kui server selle hiljem asendab, küsib OciDeck uuesti.',
  'Vertrouwen': 'Usalda',
  'Certificaat bekijken': 'Vaata sertifikaati',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Kohad, kus hoiad ja otsid oma esitlusi — kaustad selles arvutis, WebDAV-serverid, S3-ämbrid ja git-hoidlad läbisegi. Lohista need soovitud järjekorda: iga liigi ülemine kehtib vaikimisi valikuna.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  S3-salvestus: kui ühendud ämbriga, salvestatakse lõpp-punkt, ämbri nimi ja sinu juurdepääsuvõti (salajane võti turvaliselt su süsteemi võtmehoidlasse) ning esitlused, mida avad või salvestad, saadetakse sellesse salvestusteenusesse.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Git-salvestus: kui ühendud hoidlaga, salvestatakse sinu juurdepääsuluba (turvaliselt su süsteemi võtmehoidlasse) ning esitlused, mida salvestad, saadetakse sellesse serverisse commit\'idena. Hoidla töökoopia jääb sellesse seadmesse krüpteerimata.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Selle esitluse keele jaoks puuduvad haiguste nimetused. Religiooni, poliitilist veendumust ja ametiühingutermineid tuntakse ära ning kontrollnumbriga mustrid (isikukood, IBAN, pass) töötavad alati — kuid ära looda, et diagnoos leitakse.',
  'niet getest': 'testimata',
  'Werkte op': 'Töötas',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Oled sisse logitud, kuid sul pole siia ligipääsu. Parool ei ole probleem — küsi administraatorilt õigusi sellele kaustale.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Sinu luba on kehtiv, kuid ei tohi seda teha. Anna sellele rohkem õigusi või oota, kui forge rakendab piirangut.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Luba on kehtiv, kuid ei tohi seda teha — anna sellele hoidlale rohkem õigusi.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Sisse logitud, kuid ligipääsu pole — parool ei ole probleem. Küsi õigusi sellele kaustale.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'See näeb välja nagu täielik DAV-URL. Nextcloudi puhul tuletab OciDeck selle tee ise — siia kuulub ainult server.',
  'Overnemen': 'Rakenda',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'WebDAV ei ole (õigesti) seadistatud — kontrolli serveri andmeid jaotises Seaded → Salvestusruum.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Git-hoidla ei ole (õigesti) seadistatud — kontrolli serverit, omanikku ja hoidlat jaotises Seaded → Salvestusruum.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Forge\'i serveri nime ei ole olemas või seda ei õnnestu leida. Kontrolli serveri URL-i trükivea suhtes.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Sellel forge\'il on privaat- või LAN-aadress. Märgi see usaldusväärseks sisemiseks jaotises Seaded → Salvestusruum.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Forge ei ole kättesaadav — kontrolli ühendust ja serveri URL-i.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Forge\'i sisselogimine ebaõnnestus. Kontrolli luba: see vajab hoidla lugemisõigust ja salvestamiseks kirjutamisõigust.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Hoidlast ei leitud — või sinu luba ei tohi seda näha.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Forge tagastas vea. Proovi hiljem uuesti.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'See aadress ei vasta nagu forge. Kas forge\'i tüüp jaotises Seaded → Salvestusruum on õige?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Seadista kõigepealt WebDAV-server jaotises Seaded → Salvestusruum.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Vajalik, kui forge töötab privaat- või koduvõrgus. Ilma selle liputa keeldub turvakontroll privaataadressist.',
  'Vul server-URL, eigenaar en repository in':
      'Täida serveri URL, omanik ja hoidla',
  'de standaardbranch heet': 'vaikeharu nimi on',
  'die wordt voortaan gebruikt': 'seda kasutatakse edaspidi',
  'de repository is nog leeg; de eerste opslag vult hem':
      'hoidla on veel tühi; esimene salvestus täidab selle',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'märkus: see luba lubab ainult lugeda, seega salvestamine ebaõnnestub',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Sisselogimine ebaõnnestus — kontrolli luba. See vajab hoidla lugemisõigust ja salvestamiseks kirjutamisõigust.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Hoidlat ei leitud — või sinu luba ei tohi seda näha. Kontrolli omanikku ja hoidla nime.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'See aadress ei vasta nagu forge. Kas valitud forge\'i tüüp on õige?',
  'kenteken': 'registreerimisnumber',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Selle esitluse keele jaoks pole eriliigiliste isikuandmete märksõnaloendit. Kontrollnumbriga mustrid (isikukood, IBAN, pass) töötavad; sõnu nagu "diagnoos" või "kahtlustatav" ei tuvastata.',
  'Landpakketten voor identificatienummers':
      'Riikide paketid isikukoodide jaoks',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Numbrid nagu Hollandi BSN või Poola PESEL on riigipõhised. Kogu Euroopa on sisse lülitatud, sest enamikul neist numbritest on kontrollnumber: nende sisselülitamine ei maksa peaaegu ühtegi valehäiret. IBAN, e-post, saladused ja passiread on sellest sõltumatud ja kontrollitakse alati.',
